import{_ as e,a0 as l,w as n,s as p,ao as u,I as s,x as o,a1 as r,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Linux 有问必答：如何从VirtualBox中从主机访问NAT客户机 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 有问必答：如何从VirtualBox中从主机访问NAT客户机 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 有问必答：如何从VirtualBox中从主机访问NAT客户机 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 有问必答：如何从VirtualBox中从主机访问NAT客户机 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141125 Linux FAQs with Answers--How to access a NAT guest from host with VirtualBox","title":"Linux 有问必答：如何从VirtualBox中从主机访问NAT客户机","tag":"201412","desc":""},"relativePath":"201412/20141125 Linux FAQs with Answers--How to access a NAT guest from host with VirtualBox.md","filePath":"[post].md"}'),x={name:"201412/20141125 Linux FAQs with Answers--How to access a NAT guest from host with VirtualBox.md"};function m(g,t,c,f,T,d){const a=l("Link");return n(),p("div",null,[t[11]||(t[11]=u(`<h1 id="linux-有问必答-如何从virtualbox中从主机访问nat客户机" tabindex="-1">Linux 有问必答：如何从VirtualBox中从主机访问NAT客户机 <a class="header-anchor" href="#linux-有问必答-如何从virtualbox中从主机访问nat客户机" aria-label="Permalink to “Linux 有问必答：如何从VirtualBox中从主机访问NAT客户机”">​</a></h1><blockquote><p><strong>提问</strong>: 我有一台运行在VirtualBox上的使用NAT的虚拟机，因此虚拟机会被VirtualBox分配一个私有IP地址(10.x.x.x)。如果我想要从主机SSH到虚拟机中，我该怎么做？</p></blockquote><p>VirtualBox对虚拟机支持几种不同的网络方式，其中一种是NAT网络。当虚拟机启用NAT后，VirtualBox会自动在虚拟机和主机之间进行网络翻译，因此你不必在虚拟机和主机之间配置任何东西。这也意味着NAT中的虚拟机对于外部网络以及主机本身是不可见的。这会在你想要从主机访问虚拟机时会产生问题（比如SSH）。</p><p>如果你想从VirtualBox的NAT环境的虚拟机，你可以在GUI或者命令行下启用VirtualBox NAT的端口转发。本篇教程将会演示<strong>如何通过启用22端口转发而从主机SSH连接到NAT环境的客户机</strong>。如果你先想要从HTTP访问NAT的客户机，用80端口代替22端口即可。</p><h3 id="通过gui配置virtualbox端口转发" tabindex="-1">通过GUI配置VirtualBox端口转发 <a class="header-anchor" href="#通过gui配置virtualbox端口转发" aria-label="Permalink to “通过GUI配置VirtualBox端口转发”">​</a></h3><p>在VirtualBox中选择你想要访问的虚拟机，打开虚拟机的“设置”。点击左侧的“网络”菜单，点击网络适配选项的“高级”。</p><p><img src="https://farm8.staticflickr.com/7583/15797904856_2753dc785e_z.jpg" alt=""></p><p>点击“端口转发”按钮</p><p><img src="https://farm8.staticflickr.com/7527/15636152708_cf2be7c7e8_z.jpg" alt=""></p><p>你会看到一个配置端口转发规则的窗口。点击右上角的“添加”图标。</p><p><img src="https://farm8.staticflickr.com/7489/15636391217_48a9954480_z.jpg" alt=""></p><p>就会看到像下面那样的转发规则。</p><ul><li><strong>Name</strong>: SSH (可以是任意唯一名)</li><li><strong>Protocol</strong>: TCP</li><li><strong>Host IP</strong>: 127.0.0.1</li><li><strong>Host Port</strong>: 2222 (任何大于1024未使用的端口)</li><li><strong>Guest IP</strong>: 虚拟机IP</li><li><strong>Guest Port</strong>: 22 (SSH 端口)</li></ul><p><img src="https://farm6.staticflickr.com/5603/15202135853_02a07c3212_o.png" alt=""></p><p>端口转发的规则会自动在你启动虚拟机的时候启用。为了验证。可以在你启用虚拟机后检查端口2222是否被VirtualBox开启了。</p><pre><code>$ sudo netstat -nap | grep 2222 
</code></pre><p><img src="https://farm8.staticflickr.com/7461/15819682411_6bb9707f8a_z.jpg" alt=""></p><p>现在端口转发可以使用了，你可以用下面的命令SSH到虚拟机。</p><pre><code> $ ssh -p 2222 &lt;login&gt;@127.0.0.1 
</code></pre><p>发送到127.0.0.1:2222的登录请求会自动被VirtualBox翻译成10.0.2.15:22，这可以让你SSH到虚拟机中。</p><h3 id="通过命令行配置virtualbox端口转发" tabindex="-1">通过命令行配置VirtualBox端口转发 <a class="header-anchor" href="#通过命令行配置virtualbox端口转发" aria-label="Permalink to “通过命令行配置VirtualBox端口转发”">​</a></h3><p>VirtualBox有一个称为VBoxManage的命令行管理工具。使用命令行工具，你也可以为你的虚拟机设置端口转发。</p><p>下面的命令会为IP地址为10.0.2.15的虚拟机设置一个名字为&quot;centos7&quot;的端口转发规则，SSH的端口号为22,映射到本地主机的端口为2222。规则的名字（本例中是SSH）必须是唯一的。</p><pre><code>$ VBoxManage modifyvm &quot;centos7&quot; --natpf1 &quot;SSH,tcp,127.0.0.1,2222,10.0.2.15,22&quot; 
</code></pre><p>规则创建之后，你可以用下面的命令来验证。</p><pre><code> $ VBoxManage showvminfo &quot;centos7&quot; | grep NIC 
</code></pre><p><img src="https://farm8.staticflickr.com/7559/15636458427_7a0959900c_z.jpg" alt=""></p><hr>`,28)),s("p",null,[t[1]||(t[1]=o("via: ",-1)),r(a,{href:"http://ask.xmodulo.com/access-nat-guest-from-host-virtualbox.html"},{default:i(()=>[...t[0]||(t[0]=[o("http://ask.xmodulo.com/access-nat-guest-from-host-virtualbox.html",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=o("译者：",-1)),r(a,{href:"https://github.com/geekpi"},{default:i(()=>[...t[2]||(t[2]=[o("geekpi",-1)])]),_:1}),t[5]||(t[5]=o(" 校对：",-1)),r(a,{href:"https://github.com/wxy"},{default:i(()=>[...t[3]||(t[3]=[o("wxy",-1)])]),_:1})]),s("p",null,[t[8]||(t[8]=o("本文由 ",-1)),r(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...t[6]||(t[6]=[o("LCTT",-1)])]),_:1}),t[9]||(t[9]=o(" 原创翻译，",-1)),r(a,{href:"http://linux.cn/"},{default:i(()=>[...t[7]||(t[7]=[o("Linux中国",-1)])]),_:1}),t[10]||(t[10]=o(" 荣誉推出",-1))])])}const A=e(x,[["render",m]]);export{_ as __pageData,A as default};
